-- seller performance by state
select
    s.seller_state,
    count(distinct i.seller_id) as active_sellers,
    count(distinct i.order_id) as total_orders,
    count(*) as total_items,
    round(sum(i.price), 2) as product_sales,
    round(sum(i.freight_value), 2) as freight_charges,
    round(100.0 * sum(i.price) / nullif(sum(sum(i.price)) over (), 0), 2) as sales_share_pct
from mart.fact_order_items i
join mart.dim_sellers s
    on i.seller_id = s.seller_id
where i.order_status = 'delivered'
group by s.seller_state
order by product_sales desc;

