-- top 5 sellers by month

with monthly_seller_sales as (
	select
		i.seller_id,
		date_trunc('month', i.purchase_date)::date as month,
		count(distinct i.order_id) as total_orders,
		round(sum(i.price), 2) as product_sales
	from mart.fact_order_items i
	where i.order_status = 'delivered'
		and i.purchase_date is not null 
		and i.seller_id is not null
	group by i.seller_id, date_trunc('month', i.purchase_date)::date
),
seller_ranking as (
	select
		seller_id,
		month,
		total_orders,
		product_sales,
		row_number() over (partition by month order by product_sales desc, seller_id) as seller_rank
	from monthly_seller_sales
)

select
	month,
	seller_id,
	total_orders,
	product_sales,
	seller_rank
from seller_ranking
where seller_rank <= 5
order by month, seller_rank;